#include <bits/stdc++.h>
using namespace std;
template<typename T> inline void checkMin(T &a, T b) { if(b<a) a=b; }
template<typename T> inline void checkMax(T &a, T b) { if(a<b) a=b; }
#define X first
#define Y second
#define MP make_pair
#define PB push_back
#define SZ(c) int((c).size())
#define ALL(c) (c).begin(),(c).end()
#define REP(i,n) for (int i=0;i<int(n);++i)
typedef long long lint;
typedef vector<int> VI;
typedef pair<int, int> PII;

const int MOD = 1e9 + 7;

struct Matrix {
  static const int MAXN = 32;
  int N;
  int a[MAXN][MAXN];

  void initialize(int _N, int _V) {
    N = _N;
    fill(a[0], a[N], _V);
  }

  void matrix_multiply(const Matrix& b) {
    static Matrix temp, copyA, copyB;
    REP (i, N) REP (j, N)
      copyA.a[i][j] = a[i][j], copyB.a[i][j] = b.a[i][j];
    REP (i, N) REP (j, N) {
      lint t = 0;
      REP (k, N) t += lint(copyA.a[i][k]) * copyB.a[k][j] % MOD;
      a[i][j] = t % MOD;
    }
  }
} A[64][32], prefix[64][32], suffix[64][32];

lint n;
int k;

void precompute_values(int index) {
  prefix[index][1] = A[index][0];
  for (int j = 2; j <= k; ++j) {
    prefix[index][j] = prefix[index][j - 1];
    prefix[index][j].matrix_multiply(A[index][j - 1]);
  }
  suffix[index][k - 1] = A[index][k - 1];
  for (int j = k - 2; j >= 0; --j) {
    suffix[index][j] = A[index][j];
    suffix[index][j].matrix_multiply(suffix[index][j + 1]);
  }
}

int sum_digits(lint number) {
  int total = 0;
  for (; number; number /= k) {
    (total += number % k) %= k;
  }
  return total;
}

Matrix get_result(lint number, int m) {
  if (number < k) {
    Matrix res = A[m][0];
    for (int i = 1; i < number; ++i) {
      res.matrix_multiply(A[m][i]);
    }
    return res;
  }
  Matrix res = get_result(number / k, m + 1);
  int x = sum_digits(number / k);
  for (int i = 0; i < number % k; ++i) {
    res.matrix_multiply(A[m][(x + i) % k]);
  }
  return res;
}

int main() {
  cin >> n >> k;
  REP (i, k) {
    A[0][i].init(k + 1, 0);
    REP (j, k + 1) {
      A[0][i].a[j][j] = 1;
      A[0][i].a[j][i] = 1;
    }
  }
  for (int m = 1; pow(k, m) - 1000 <= n; ++m) {
    precompute_values(m - 1);
    REP (x, k) {
      A[m][x] = suffix[m - 1][x];
      if (x > 0) {
        A[m][x].matrix_multiply(prefix[m - 1][x]);
      }
    }
  }
  Matrix finalMat = get_result(n, 0);
  int totalAns = 0;
  REP (i, k + 1) {
    (totalAns += finalMat.a[k][i]) %= MOD;
  }
  cout << totalAns << endl;
  return 0;
}
